from pathlib import Path\n    39\t\n    40\tsys.path.insert(0, str(Path(__file__).resolve().parent))\n    41\tfrom wf_util import LayerError, atomic_write, check_bracket_free, default_repo_root, utcnow\n    42\t\n    43\t#: One page of the REST pagination loop; also the adoption search window.\n    44\tPAGE = 100\n    45\t\n    46\t#: GitHub caps comment/review bodies at 65536 characters; leave headroom for\n    47\t#: the marker line and the truncation notice.\n    48\tCOMMENT_BODY_LIMIT = 60000\n    49\t\n    50\t_TRANSIENT_RE = re.compile(\n    51\t    r\"(?i)(timed? ?out|connection|temporar|unavailable|network|reset by peer|\"\n    52\t    r\"tls|eof|http (?:429|5\\d\\d)|rate limit|bad gateway|service unavailable)\"\n    53\t)\n    54\t\n    55\t_REMOTE_RE = re.compile(r\"github\\.com[:/]([^/]+/[^/\\s]+?)(?:\\.git)?$\")\n    56\t\n    57\t\n    58\tdef gh_bin() -> str:\n    59\t    override = os.environ.get(\"MIPSTARRE_GH\")\n    60\t    if override:\n    61\t        return override\n    62\t    found = shutil.which(\"gh\")\n    63\t    if found:\n    64\t        return found\n    65\t    fallback = Path.home() / \".local\" / \"bin\" / \"gh\"\n    66\t    if fallback.exists():\n    67\t        return str(fallback)\n    68\t    raise LayerError(\"gh CLI not found (set MIPSTARRE_GH or install gh)\")\n    69\t\n    70\t\n    71\tdef repo_slug(repo_root: Path | None = None) -> str:\n    72\t    override = os.environ.get(\"MIPSTARRE_GITHUB_REPO\")\n    73\t    if override:\n    74\t        return override\n    75\t    root = repo_root or default_repo_root()\n    76\t    proc = subprocess.run(\n    77\t        [\"git\", \"-C\", str(root), \"remote\", \"get-url\", \"github\"],\n    78\t        capture_output=True, text=True,\n    79\t    )\n    80\t    if proc.returncode == 0:\n    81\t        match = _REMOTE_RE.search(proc.stdout.strip())\n    82\t        if match:\n    83\t            return match.group(1)\n    84\t    raise LayerError(\n    85\t        \"cannot resolve the GitHub repo: set MIPSTARRE_GITHUB_REPO=owner/repo \"\n    86\t        \"or add a 'github' remote to the primary checkout\"\n    87\t    )\n    88\t\n    89\t\n    90\tdef run_gh(args: list[str], *, input_text: str | None = None,\n    91\t           mutation: bool = False, idempotent: bool = False,\n    92\t           retries: int = 3) -> str:\n    93\t    \"\"\"Run ``gh`` and return stdout; raise ``LayerError`` on final failure.\n    94\t\n    95\t    A non-idempotent mutation is attempted exactly once — the caller owns\n    96\t    ambiguity recovery by re-reading state.  Reads and idempotent mutations\n    97\t    retry on transient failures with linear backoff.\n    98\t    \"\"\"\n    99\t    attempts = 1 if (mutation and not idempotent) else max(1, retries)\n   100\t    env = dict(os.environ, GH_PROMPT_DISABLED=\"1\", GH_NO_UPDATE_NOTIFIER=\"1\",\n   101\t               NO_COLOR=\"1\", GH_PAGER=\"cat\")\n   102\t    last_err = \"\"\n   103\t    for attempt in range(1, attempts + 1):\n   104\t        proc = subprocess.run(\n   105\t            [gh_bin(), *args], input=input_text,\n   106\t            capture_output=True, text=True, env=env,\n   107\t        )\n   108\t        if proc.returncode == 0:\n   109\t            return proc.stdout\n   110\t        last_err = (proc.stderr or proc.stdout or \"\").strip()\n   111\t        if attempt < attempts and _TRANSIENT_RE.search(last_err):\n   112\t            time.sleep(5 * attempt)\n   113\t            continue\n   114\t        break\n   115\t    raise LayerError(f\"gh {' '.join(args[:3])}... failed: {last_err[:2000]}\")\n   116\t\n   117\t\n   118\tdef api(path: str, *, method: str | None = None, payload: dict | None = None,\n   119\t        paginate: bool = False, mutation: bool = False,\n   120\t        idempotent: bool = False, absolute: bool = False):\n   121\t    \"\"\"Call the REST API under ``repos/<slug>/`` (or an absolute *path*).\n   122\t\n   123\t    Pagination is manual (``?per_page=100&page=N``) so nothing here depends on\n   124\t    a modern ``gh``.  Returns parsed JSON (``None`` for an empty response).\n   125\t    \"\"\"\n   126\t    full = path if absolute else f\"repos/{repo_slug()}/{path}\"\n   127\t\n   128\t    def one(page_path: str):\n   129\t        args = [\"api\", page_path]\n   130\t        if method:\n   131\t            args += [\"-X\", method]\n   132\t        input_text = None\n   133\t        if payload is not None:\n   134\t            args += [\"--input\", \"-\"]\n   135\t            input_text = json.dumps(payload)\n   136\t        out = run_gh(args, input_text=input_text, mutation=mutation,\n   137\t                     idempotent=idempotent)\n   138\t        return json.loads(out) if out.strip() else None\n   139\t\n   140\t    if not paginate:\n   141\t        return one(full)\n   142\t\n   143\t    sep = \"&\" if \"?\" in full else \"?\"\n   144\t    rows: list = []\n   145\t    page = 1\n   146\t    while True:\n   147\t        batch = one(f\"{full}{sep}per_page={PAGE}&page={page}\")\n   148\t        if not batch:\n   149\t            break\n   150\t        rows.extend(batch)\n   151\t        if len(batch) < PAGE:\n   152\t            break\n   153\t        page += 1\n   154\t    return rows\n   155\t\n   156\t\n   157\t# ---------------------------------------------------------------------------\n   158\t# Commit statuses — CI and review evidence, bound to the exact head SHA\n   159\t# ---------------------------------------------------------------------------\n   160\t\n   161\tdef post_status(sha: str, context: str, state: str, description: str = \"\",\n   162\t                target_url: str | None = None) -> None:\n   163\t    \"\"\"Post one commit status.  Idempotent by content: latest-per-context wins.\"\"\"\n   164\t    if state not in (\"pending\", \"success\", \"failure\", \"error\"):\n   165\t        raise LayerError(f\"invalid status state {state!r}\")\n   166\t    payload = {\"state\": state, \"context\": context,\n   167\t               \"description\": description[:140]}\n   168\t    if target_url:\n   169\t        payload[\"target_url\"] = target_url\n   170\t    api(f\"statuses/{sha}\", method=\"POST\", payload=payload,\n   171\t        mutation=True, idempotent=True)\n   172\t\n   173\t\n   174\tdef latest_statuses(sha: str) -> dict[str, dict]:\n   175\t    \"\"\"Latest status per context on *sha* (rows arrive newest-first).\"\"\"\n   176\t    rows = api(f\"commits/{sha}/statuses\", paginate=True)\n   177\t    latest: dict[str, dict] = {}\n   178\t    for row in rows:\n   179\t        context = row.get(\"context\") or \"\"\n   180\t        if context and context not in latest:\n   181\t            latest[context] = {\"state\": row.get(\"state\"),\n   182\t                               \"description\": row.get(\"description\") or \"\",\n   183\t                               \"created_at\": row.get(\"created_at\") or \"\"}\n   184\t    return latest\n   185\t\n   186\t\n   187\t# ---------------------------------------------------------------------------\n   188\t# Pull requests\n   189\t# ---------------------------------------------------------------------------\n   190\t\n   191\tdef pr_view(number: int) -> dict:\n   192\t    return api(f\"pulls/{number}\")\n   193\t\n   194\t\n   195\tdef pr_for_branch(branch: str) -> dict | None:\n   196\t    \"\"\"The unique open PR whose head is *branch*, or None.\"\"\"\n   197\t    owner = repo_slug().split(\"/\")[0]\n   198\t    head = urllib.parse.quote(f\"{owner}:{branch}\", safe=\":\")\n   199\t    rows = api(f\"pulls?state=open&head={head}\", paginate=True)\n   200\t    if len(rows) > 1:\n   201\t        raise LayerError(f\"multiple open PRs for head {branch!r}\")\n   202\t    return rows[0] if rows else None\n   203\t\n   204\t\n   205\tdef ensure_pr_comment(number: int, marker: str, body: str) -> int:\n   206\t    \"\"\"Create or update the single PR comment carrying *marker*.\n   207\t\n   208\t    The marker (an HTML comment) is the idempotency key: an existing comment\n   209\t    is PATCHed in place; after an ambiguous POST failure the list is re-read\n   210\t    and an adopted comment is not re-posted.\n   211\t    \"\"\"\n   212\t    full = _marked_body(marker, body)\n   213\t    existing = _find_comment(number, marker)\n   214\t    if existing is not None:\n   215\t        api(f\"issues/comments/{existing}\", method=\"PATCH\",\n   216\t            payload={\"body\": full}, mutation=True, idempotent=True)\n   217\t        return existing\n   218\t    try:\n   219\t        created = api(f\"issues/{number}/comments\", method=\"POST\",\n   220\t                      payload={\"body\": full}, mutation=True)\n   221\t        return int(created[\"id\"])\n   222\t    except LayerError:\n   223\t        adopted = _find_comment(number, marker)\n   224\t        if adopted is not None:\n   225\t            return adopted\n   226\t        raise\n   227\t\n   228\t\n   229\tdef _find_comment(number: int, marker: str) -> int | None:\n   230\t    for row in api(f\"issues/{number}/comments\", paginate=True):\n   231\t        if marker in (row.get(\"body\") or \"\"):\n   232\t            return int(row[\"id\"])\n   233\t    return None\n   234\t\n   235\t\n   236\tdef _marked_body(marker: str, body: str) -> str:\n   237\t    if len(body) > COMMENT_BODY_LIMIT:\n   238\t        body = body[:COMMENT_BODY_LIMIT] + \"\\n\\n*(truncated; the full text is in runtime storage / telemetry)*\"\n   239\t    return f\"{marker}\\n{body}\"\n   240\t\n   241\t\n   242\tdef post_review(number: int, commit_id: str, marker: str, body: str) -> str:\n   243\t    \"\"\"Post one COMMENT review bound to *commit_id*; marker-idempotent.\n   244\t\n   245\t    Single-account repos cannot self-APPROVE, so every local verdict is a\n   246\t    COMMENT review; adverseness travels in the ``local-review/summary`` status,\n   247\t    not in a review state.  Returns ``\"exists\"`` or the new review id.\n   248\t    \"\"\"\n   249\t    for row in api(f\"pulls/{number}/reviews\", paginate=True):\n   250\t        if row.get(\"commit_id\") == commit_id and marker in (row.get(\"body\") or \"\"):\n   251\t            return \"exists\"\n   252\t    payload = {\"commit_id\": commit_id, \"event\": \"COMMENT\",\n   253\t               \"body\": _marked_body(marker, body)}\n   254\t    try:\n   255\t        created = api(f\"pulls/{number}/reviews\", method=\"POST\",\n   256\t                      payload=payload, mutation=True)\n   257\t        return str(created.get(\"id\"))\n   258\t    except LayerError:\n   259\t        for row in api(f\"pulls/{number}/reviews\", paginate=True):\n   260\t            if row.get(\"commit_id\") == commit_id and marker in (row.get(\"body\") or \"\"):\n   261\t                return \"adopted\"\n   262\t        raise\n   263\t\n   264\t\n   265\tdef pr_reviews(number: int) -> list[dict]:\n   266\t    return api(f\"pulls/{number}/reviews\", paginate=True)\n   267\t\n   268\t\n   269\tdef merge_pr(number: int, sha: str) -> str:\n   270\t    \"\"\"Merge PR *number* iff its head is exactly *sha*; verify topology.\n   271\t\n   272\t    The REST ``sha`` parameter makes GitHub reject the merge when the head\n   273\t    moved — the atomic exact-head guard, independent of the gh CLI version.\n   274\t    Returns the merge commit SHA after verifying it has exactly two parents\n   275\t    with the frozen head second.\n   276\t    \"\"\"\n   277\t    put_error = \"\"\n   278\t    try:\n   279\t        api(f\"pulls/{number}/merge\", method=\"PUT\",\n   280\t            payload={\"sha\": sha, \"merge_method\": \"merge\"}, mutation=True)\n","exit_code":0,"status":"completed"}}
