onally link as a sub-issue.\n   316\t\n   317\t    With *key*, a ``<!-- mipstarre-issue-key: ... -->`` marker is embedded and\n   318\t    an ambiguous create failure adopts the existing issue instead of\n   319\t    duplicating it.\n   320\t    \"\"\"\n   321\t    check_bracket_free(title, \"issue title\")\n   322\t    if labels:\n   323\t        known = set(list_labels())\n   324\t        missing = sorted(set(labels) - known)\n   325\t        if missing:\n   326\t            raise LayerError(\n   327\t                f\"labels not in the repository: {missing} — create them on \"\n   328\t                f\"GitHub first (gh label create) or drop them\")\n   329\t    marker = f\"<!-- mipstarre-issue-key: {key} -->\" if key else None\n   330\t    full_body = f\"{marker}\\n{body}\" if marker else body\n   331\t    # Adoption never returns early: the parent link below must run even when the\n   332\t    # issue already exists (a prior run may have died between create and link).\n   333\t    number = _find_issue_by_marker(marker) if marker else None\n   334\t    if number is None:\n   335\t        payload: dict = {\"title\": title, \"body\": full_body}\n   336\t        if labels:\n   337\t            payload[\"labels\"] = list(labels)\n   338\t        try:\n   339\t            created = api(\"issues\", method=\"POST\", payload=payload, mutation=True)\n   340\t            number = int(created[\"number\"])\n   341\t        except LayerError:\n   342\t            if marker:\n   343\t                number = _find_issue_by_marker(marker)\n   344\t            if number is None:\n   345\t                raise\n   346\t    if parent is not None:\n   347\t        add_sub_issue(parent, number)\n   348\t    return number\n   349\t\n   350\t\n   351\tdef _find_issue_by_marker(marker: str) -> int | None:\n   352\t    rows = api(\"issues?state=all&sort=created&direction=desc\", paginate=True)\n   353\t    for row in rows or []:\n   354\t        if \"pull_request\" in row:\n   355\t 