issue_new.py --title \"Formalize the Pauli basis test soundness bound\" \\\n    29\t                 --body-file /tmp/body.md --label formalization\n    30\t    issue_new.py --title \"Tracking - Pauli basis test\" --body \"...\" \\\n    31\t                 --parent 12 --key qpbt-tracking-pauli\n    32\t    issue_new.py --help\n    33\t\"\"\"\n    34\t\n    35\tfrom __future__ import annotations\n    36\t\n    37\timport argparse\n    38\timport hashlib\n    39\timport sys\n    40\tfrom pathlib import Path\n    41\t\n    42\tsys.path.insert(0, str(Path(__file__).resolve().parent))\n    43\ttry:\n    44\t    import gh_common\n    45\texcept ModuleNotFoundError as exc:  # pragma: no cover - defensive\n    46\t    sys.stderr.write(\n    47\t        \"issue_new.py: cannot import local/bin/gh_common.py, which holds the \"\n    48\t        f\"GitHub layer ({exc}).\\n\"\n    49\t    )\n    50\t    raise SystemExit(2)\n    51\t\n    52\tfrom wf_util import slugify, BODY_LIMIT, TITLE_LIMIT, LayerError, sanitize  # noqa: E402\n    53\t\n    54\t\n    55\tdef flatten_labels(chunks: list[str]) -> tuple[str, ...]:\n    56\t    \"\"\"``--label a,b --label c`` -> ``(\"a\", \"b\", \"c\")``, order-preserving; comma\n    57\t    splitting is kept from the pre-0007 CLI, whose callers pass grouped lists.\"\"\"\n    58\t    names: list[str] = []\n    59\t    for chunk in chunks:\n    60\t        for name in (part.strip() for part in chunk.split(\",\")):\n    61\t            if name and name not in names:\n    62\t                names.append(name)\n    63\t    return tuple(names)\n    64\t\n    65\t\n    66\tdef create(args: argparse.Namespace) -> int:\n    67\t    title = sanitize(args.title, TITLE_LIMIT).strip()\n    68\t    if not title:\n    69\t        raise LayerError(\"--title is empty after sanitization\")\n    70\t    if args.body_file:\n    71\t        raw = Path(args.body_file).read_text(encoding=\"utf-8\")\n    72\t    else:\n    73\t        raw = args.body or \"\"\n    74\t    # Bodies round-trip through GitHub, where anyone with read access can quote\n    75\t    # them back into an agent prompt, so they are untrusted on the way out too\n    76\t    # (wf_util.sanitize breaks ``` fences and strips control characters).\n    77\t    body = sanitize(raw, BODY_LIMIT).strip()\n    78\t    if not body:\n    79\t        raise LayerError(\n    80\t            \"an issue body is required: pass --body-file PATH or --body TEXT. \"\n    81\t            \"The old --template scaffolds are gone; GitHub's issue forms under \"\n    82\t            \".github/ISSUE_TEMPLATE/ are where boilerplate belongs now.\"\n    83\t        )\n    84\t    labels = flatten_labels(args.label)\n    85\t\n    86\t    if args.dry_run:\n    87\t        sys.stdout.write(\n    88\t            f\"[dry-run] would create issue {title!r} labels={list(labels)} \"\n    89\t            f\"parent={args.parent} key={args.key} ({len(body)} body chars)\\n\"\n    90\t        )\n    91\t        return 0\n    92\t\n    93\t    # Every create is adoption-safe: without an explicit --key the slug plus a\n    94\t    # short digest of the FULL title is the key, so a retried create adopts —\n    95\t    # and two distinct titles sharing a truncated slug cannot alias (round 2, F12).\n    96\t    auto_key = f\"{slugify(title)}-{hashlib.sha256(title.encode()).hexdigest()[:8]}\"\n    97\t    number = gh_common.issue_create(\n    98\t        title, body, labels=labels, parent=args.parent,\n    99\t        key=args.key or auto_key\n   100\t    )\n   101\t    # Bare number on stdout: shell callers capture it with $(...).\n   102\t    sys.stdout.write(f\"{number}\\n\")\n   103\t    return 0\n   104\t\n   105\t\n   106\tdef _parse_args(argv: list[str]) -> argparse.Namespace:\n   107\t    parser = argparse.ArgumentParser(\n   108\t        prog=\"issue_new.py\",\n   109\t        description=__doc__,\n   110\t        formatter_class=argparse.RawDescriptionHelpFormatter,\n   111\t    )\n   112\t    parser.add_argument(\"--title\", required=True,\n   113\t                        help=\"bracket-free issue title (docs/CONTRIBUTING.md:122-124)\")\n   114\t    body = parser.add_mutually_exclusive_group(required=True)\n   115\t    body.add_argument(\"--body-file\", type=Path, metavar=\"PATH\",\n   116\t                      help=\"file holding the issue body\")\n   117\t    body.add_argument(\"--body\", metavar=\"TEXT\",\n   118\t                      help=\"issue body as a literal string\")\n   119\t    parser.add_argument(\"--label\", action=\"append\", default=[], metavar=\"NAME\",\n   120\t                        help=\"repository label; repeatable, comma lists accepted. \"\n   121\t                             \"Unknown labels are rejected — create them on GitHub \"\n   122\t                             \"first (gh_common.py:318-323)\")\n   123\t    parser.add_argument(\"--parent\", type=int, metavar=\"N\",\n   124\t                        help=\"attach the new issue as a native sub-issue of #N\")\n   125\t    parser.add_argument(\"--key\", metavar=\"K\",\n   126\t                        help=\"idempotency key: embeds a marker so a retried \"\n   127\t                             \"create adopts the existing issue instead of \"\n   128\t                             \"opening a duplicate\")\n   129\t    parser.add_argument(\"--dry-run\", action=\"store_true\",\n   130\t                        help=\"print what would be created, call nothing\")\n   131\t    return parser.parse_args(argv)\n   132\t\n   133\t\n   134\tdef main(argv: list[str] | None = None) -> int:\n   135\t    args = _parse_args(sys.argv[1:] if argv is None else argv)\n   136\t    try:\n   137\t        return create(args)\n   138\t    except LayerError as exc:\n   139\t        sys.stderr.write(f\"issue_new.py: {exc}\\n\")\n   140\t        return 2\n   141\t\n   142\t\n   143\tif __name__ == \"__main__\":\n   144\t    raise SystemExit(main())\n","exit_code":0,"status":"completed"}}
