onally ``codex/``-prefixed.\n    34\tBRANCH_RE = re.compile(r\"^(?:(codex|claude)/)?issue-(\\d+)-([a-z0-9][a-z0-9-]*)$\")\n    35\t\n    36\t#: docs/CONTRIBUTING.md:61-62 — a closing keyword is what makes the merge close\n    37\t#: the issue, so the footer is appended only when the body carries none.  GitHub's\n    38\t#: nine auto-closing keywords, exactly; keep in sync with pr_merge.py CLOSES_RE so\n    39\t#: every reference this footer honors is one the dependency gate also sees.\n    40\tCLOSES_RE = re.compile(r\"(?i)\\b(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?):?\\s+#(\\d+)\")\n    41\t\n    42\t\n    43\tdef git(repo_root: Path, *args: str, check: bool = True) -> str:\n    44\t    \"\"\"Run git in *repo_root*; stripped stdout, or ``LayerError`` / ``\"\"``.\"\"\"\n    45\t    proc = subprocess.run([\"git\", \"-C\", str(repo_root), *args],\n    46\t                          capture_output=True, text=True)\n    47\t    if proc.returncode == 0:\n    48\t        return proc.stdout.strip()\n    49\t    if check:\n    50\t        raise LayerError(f\"git {' '.join(args[:3])} failed: \"\n    51\t                         f\"{(proc.stderr or proc.stdout).strip()[:500]}\")\n    52\t    return \"\"\n    53\t\n    54\t\n    55\tdef lint_branch(repo_root: Path, branch: str) -> None:\n    56\t    \"\"\"Reject a name, or a branch, that cannot safely become a PR head; the\n    57\t    ``issue-<id>-<slug>`` convention only warns, since the issue link now\n    58\t    travels in the body footer while ``agent.sh`` still derives names so.\"\"\"\n    59\t    check_bracket_free(branch, \"branch name\", FORBIDDEN_REF_CHARS)\n    60\t    git(repo_root, \"check-ref-format\", \"--branch\", branch)\n    61\t    if not git(repo_root, \"rev-parse\", \"--verify\", f\"refs/heads/{branch}\", check=False):\n    62\t        raise LayerError(f\"branch {branch!r} does not exist in {repo_root}; create \"\n    63\t                         \"and commit on it before opening a PR\")\n    64\t    match = BRANCH_RE.match(branch)\n    65\t    if not match or match.group(1) == \"claude\":\n    66\t        sys.stderr.write(f\"warning: branch {branch!r} is not a current-convention \"\n    67\t                         \"'issue-<id>-<slug>' / 'codex/issue-<id>-<slug>' name \"\n    68\t                         \"(DESIGN.md:106-107).\\n\")\n    69\t\n    70\t\n    71\tdef require_diff(repo_root: Path, base: str, branch: str) -> int:\n    72\t    \"\"\"Commits ahead of the base; raise when there are none.\"\"\"\n    73\t    for ref in (f\"refs/remotes/github/{base}\", base):\n    74\t        count = git(repo_root, \"rev-list\", \"--count\", f\"{ref}..{branch}\", check=False)\n    75\t        if count.isdigit():\n    76\t            if int(count) == 0:\n    77\t                raise LayerError(f\"{branch} has no commits ahead of {ref}: nothing \"\n    78\t                                 \"to review. Commit the work — never open a PR on \"\n    79\t                                 \"an empty diff.\")\n    80\t            return int(count)\n    81\t    raise LayerError(f\"cannot resolve base {base!r} locally or as github/{base}\")\n    82\t\n    83\t\n    84\tdef pr_create(title: str, head: str, base: str, body: str) -> int:\n    85\t    \"\"\"POST one PR; an ambiguous failure adopts, never retries (gh_common.py:216).\"\"\"\n    86\t    try:\n    87\t        created = gh_common.api(\"pulls\", method=\"POST\", mutation=True,\n    88\t                                payload={\"title\": title, \"head\": head,\n    89\t                                         \"base\": base, \"body\": body})\n    90\t        return int(created[\"number\"])\n    91\t    except LayerError:\n    92\t        adopted = gh_common.pr_for_branch(head)\n    93\t        if adopted is not None:\n    94\t            return int(adopted[\"number\"])\n    95\t        raise\n    96\t\n    97\t\n    98\tdef open_pr(args: argparse.Namespace) -> int:\n    99\t    repo_root = args.repo_root.resolve()\n   100\t    lint_branch(repo_root, args.branch)\n   101\t    ahead = require_diff(repo_root, args.base, args.branch)\n   102\t\n   103\t    title = sanitize(args.title, TITLE_LIMIT).strip() if args.title else \"\"\n   104\t    if title:\n   105\t        check_bracket_free(title, \"PR title\")\n   106\t    raw = Path(args.body_file).read_text(encoding=\"utf-8\") if args.body_file else \"\"\n   107\t    body = sanitize(raw, BODY_LIMIT)  # untrusted on the way out too: it will be quoted back\n   108\t    if args.issue and not any(int(n) == args.issue for n in CLOSES_RE.findall(body)):\n   109\t        body = f\"{body.rstrip()}\\n\\n---\\nCloses #{args.issue}\\n\".lstrip()\n   110\t\n   111\t    labels = [n.strip() for chunk in args.label for n in chunk.split(\",\") if n.strip()]\n   112\t    missing = sorted(set(labels) - set(gh_common.list_labels())) if labels else []\n   113\t    if missing:\n   114\t        raise LayerError(f\"labels not in the repository: {missing} — create them \"\n   115\t                         \"on GitHub first or drop them\")\n   116\t    if args.dry_run:\n   117\t        sys.stdout.write(f\"[dry-run] would push refs/heads/{args.branch} ({ahead} \"\n   118\t                         f\"ahead of {args.base}) and open {title!r} {labels}\\n\")\n   119\t        return 0\n   120\t\n   121\t    git(repo_root, \"push\", \"github\",\n   122\t        f\"refs/heads/{args.branch}:refs/heads/{args.branch}\")\n   123\t\n   124\t    existing = gh_common.pr_for_branch(args.branch)\n   125\t    if existing is not None:\n   126\t        number = int(existing[\"number\"])\n   127\t        patch = {\"title\": title} if title else {}\n   128\t        if args.body_file:\n   129\t            patch[\"body\"] = body\n   130\t        elif args.issue:\n   131\t            # No replacement body was supplied, so never overwrite the existing\n   132\t            # description; append the footer to the CURRENT body iff no closing\n   133\t            # reference to this issue is there yet.\n   134\t            current = str(existing.get(\"body\") or \"\")\n   135\t            if not any(int(n) == args.issue for n in CLOSES_RE.findall(current)):\n   136\t                patch[\"body\"] = f\"{current.rstrip()}\\n\\n---\\nCloses #{args.issue}\\n\".lstrip()\n   137\t        if patch:\n   138\t            gh_common.api(f\"pulls/{number}\", method=\"PATCH\", payload=patch,\n   139\t                          mutation=True, idempotent=True)\n   140\t        sys.stderr.write(f\"adopted the open PR for {args.branch}\\n\")\n   141\t    elif not title:\n   142\t        raise LayerError(\"--title is required to open a new PR\")\n   143\t    else:\n   144\t        number = pr_create(title, args.branch, args.base, body)\n   145\t\n   146\t    if labels:  # idempotent by content: GitHub unions the label set.\n   147\t        gh_common.api(f\"issues/{number}/labels\", method=\"POST\",\n   148\t                      payload={\"labels\": labels}, mutation=True, idempotent=True)\n   149\t    sys.stdout.write(f\"{number}\\n\")  # bare number for $(...) in the shell layer\n   150\t    return 0\n   151\t\n   152\t\n   153\tdef _parse_args(argv: list[str]) -> argparse.Namespace:\n   154\t    parser = argparse.ArgumentParser(prog=\"pr_open.py\", description=__doc__,\n   155\t                                     formatter_class=argparse.RawDescriptionHelpFormatter)\n   156\t    add = parser.add_argument\n   157\t    add(\"--branch\", required=True, help=\"head branch; must exist locally with commits\")\n   158\t    add(\"--base\", default=\"main\", help=\"merge target (default: main)\")\n   159\t    add(\"--title\", help=\"conventional-commit title; required to open a new PR\")\n   160\t    add(\"--body-file\", type=Path, metavar=\"PATH\", help=\"file holding the PR body\")\n   161\t    add(\"--label\", action=\"append\", default=[], metavar=\"NAME\",\n   162\t        help=\"repository label; repeatable, comma lists accepted\")\n   163\t    add(\"--issue\", type=int, meta