t#: Characters banned from branch names: the pair above plus the git refname\n    40\t#: metacharacters, which ``git check-ref-format`` rejects for the same\n    41\t#: structural reason — a name that travels through shell, path and regex\n    42\t#: contexts must survive all three.\n    43\tFORBIDDEN_REF_CHARS = \"[]~^:?*\\\\ \\t\"\n    44\t\n    45\t\n    46\tdef default_repo_root() -> Path:\n    47\t    \"\"\"Repository root, assuming this file stays at ``local/bin/wf_util.py``.\"\"\"\n    48\t    return Path(__file__).resolve().parents[2]\n    49\t\n    50\t\n    51\tdef cache_root() -> Path:\n    52\t    return CACHE_ROOT.expanduser()\n    53\t\n    54\t\n    55\tdef lock_dir() -> Path:\n    56\t    return cache_root() / \"locks\"\n    57\t\n    58\t\n    59\tdef utcnow() -> str:\n    60\t    \"\"\"Timestamp format used across telemetry and generated records.\"\"\"\n    61\t    return datetime.now(timezone.utc).strftime(\"%Y-%m-%dT%H:%M:%SZ\")\n    62\t\n    63\t\n    64\tclass LayerError(RuntimeError):\n    65\t    \"\"\"Operator-facing failure: printed without a traceback by ``main``.\"\"\"\n    66\t\n    67\t\n    68\t# ---------------------------------------------------------------------------\n    69\t# Untrusted-text sanitization\n    70\t# ---------------------------------------------------------------------------\n    71\t\n    72\t_CONTROL_RE = re.compile(r\"[\\u0000-\\u0008\\u000B\\u000C\\u000E-\\u001F\\u007F]\")\n    73\t\n    74\t#: Truncation limits copied from the parent's sanitize step\n    75\t#: (issue-automation.yml:124-128): title 200, body 5000.\n    76\tTITLE_LIMIT = 200\n    77\tBODY_LIMIT = 5000\n    78\t\n    79\t\n    80\tdef sanitize(text: str | None, limit: int | None = None) -> str:\n    81\t    \"\"\"Strip control characters, break ``` fences, optionally truncate.\n    82\t\n    83\t    Verbatim port of the ``Sanitize issue content`` step at\n    84\t    ``.github/workflows/issue-automation.yml:122-128``.  Issue and PR text is\n    85\t    untrusted even when it originates locally — and doubly so now that bodies\n    86\t    round-trip through GitHub, where anyone with repo read access can quote\n    87\t    them.  Fence-breaking inserts zero-width spaces so a body cannot close a\n    88\t    fenced block that frames it as data.\n    89\t    \"\"\"\n    90\t    cleaned = _CONTROL_RE.sub(\"\", text or \"\")\n    91\t    cleaned = cleaned.replace(\"```\", \"\\u200b`\\u200b`\\u200b`\")\n    92\t    if limit is not None:\n    93\t        cleaned = cleaned[:limit]\n    94\t    return cleaned\n    95\t\n    96\t\n    97\tdef check_bracket_free(value: str, what: str, chars: str = FORBIDDEN_TITLE_CHARS) -> None:\n    98\t    \"\"\"Raise when *value* carries a character that breaks name propagation.\n    99\t\n   100\t    docs/CONTRIBUTING.md:122-124: \"Avoid prefixes like ``[Chapter 9] ...``:\n   101\t    bot-generated branch names inherit those characters, and ``]`` breaks part\n   102\t    of the PR automation stack.\"  Slugs and branch names derive from titles\n   103\t    mechanically, so the rule is enforced at the point of creation.\n   104\t    \"\"\"\n   105\t    bad = sorted({c for c in value if c in chars})\n   106\t    if bad:\n   107\t        rendered = \" \".join(repr(c) for c in bad)\n   108\t        raise LayerError(\n   109\t            f\"{what} contains reserved character(s) {rendered}: {value!r}\\n\"\n   110\t            \"Bracketed prefixes leak into branch names and break name-derived \"\n   111\t            \"automation (docs/CONTRIBUTING.md:122-124). Rewrite the text, e.g. \"\n   112\t            \"'Chapter 9 - finish the sandwich-chain corollaries'.\"\n   113\t        )\n   114\t\n   115\t\n   116\tdef slugify(title: str, max_words: int = 8) -> str:\n   117\t    \"\"\"Lowercase, hyphenated, bracket-free slug derived from a title.\"\"\"\n   118\t    lowered = title.lower()\n   119\t    words = [w for w in re.split(r\"[^a-z0-9]+\", lowered) if w]\n   120\t    if not words:\n   121\t        raise LayerError(f\"title {title!r} yields an empty slug; use words a-z0-9\")\n   122\t    slug = \"-\".join(words[:max_words])[:60].strip(\"-\")\n   123\t    if not re.fullmatch(r\"[a-z0-9][a-z0-9-]*\", slug):\n   124\t        raise LayerError(f\"derived slug {slug!r} is not bracket-free lowercase-kebab\")\n   125\t    return slug\n   126\t\n   127\t\n   128\t# ---------------------------------------------------------------------------\n   129\t# Advisory locking\n   130\t# ---------------------------------------------------------------------------\n   131\t\n   132\t_HELD: dict[str, int] = {}\n   133\t\n   134\t\n   135\t@contextmanager\n   136\tdef file_lock(name: str, *, timeout_note: str | None = None) -> Iterator[None]:\n   137\t    \"\"\"Exclusive advisory lock under ``~/.cache/mipstarre-dev/locks/<name>``.\n   138\t\n   139\t    The hazard is two agent sessions mutating the same runtime state; a\n   140\t    per-entity ``flock`` plus the atomic writer below covers it.  Re-entrant\n   141\t    within one process so a caller may hold a lock while a helper re-acquires\n   142\t    it.\n   143\t    \"\"\"\n   144\t    if _HELD.get(name):\n   145\t        _HELD[name] += 1\n   146\t        try:\n   147\t            yield\n   148\t        finally:\n   149\t            _HELD[name] -= 1\n   150\t        return\n   151\t\n   152\t    directory = lock_dir()\n   153\t    directory.mkdir(parents=True, exist_ok=True)\n   154\t    path = directory / f\"{name}.lock\"\n   155\t    fd = os.open(str(path), os.O_CREAT | os.O_RDWR, 0o644)\n   156\t    try:\n   157\t        try:\n   158\t            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)\n   159\t        except OSError as exc:\n   160\t            if exc.errno not in (errno.EAGAIN, errno.EACCES):\n   161\t                raise\n   162\t            sys.stderr.write(f\"waiting for lock {path} ...\\n\")\n   163\t            fcntl.flock(fd, fcntl.LOCK_EX)\n   164\t        os.ftruncate(fd, 0)\n   165\t        os.write(fd, f\"{os.getpid()}\\n\".encode())\n   166\t        _HELD[name] = 1\n   167\t        try:\n   168\t            yield\n   169\t        finally:\n   170\t            _HELD.pop(name, None)\n   171\t            fcntl.flock(fd, fcntl.LOCK_UN)\n   172\t    finally:\n   173\t        os.close(fd)\n   174\t\n   175\t\n   176\t# ---------------------------------------------------------------------------\n   177\t# Atomic writes\n   178\t# ---------------------------------------------------------------------------\n   179\t\n   180\tdef atomic_write(path: Path, text: str) -> None:\n   181\t    \"\"\"Write *text* to *path* via tempfile + ``os.replace``.\n   182\t\n   183\t    Used for runtime artifacts and telemetry snapshots: a half-written file\n   184\t    must never be observable.\n   185\t    \"\"\"\n   186\t    path.parent.mkdir(parents=True, exist_ok=True)\n   187\t    fd, tmp = tempfile.mkstemp(dir=str(path.parent), prefix=f\".{path.name}.\", suffix=\".tmp\")\n   188\t    try:\n   189\t        with os.fdopen(fd, \"w\", encoding=\"utf-8\") as handle:\n   190\t            handle.write(text)\n   191\t            handle.flush()\n   192\t            os.fsync(handle.fileno())\n   193\t        os.replace(tmp, path)\n   194\t    except BaseException:\n   195\t        try:\n   196\t            os.unlink(tmp)\n   197\t        except OSError:\n   198\t            pass\n   199\t        raise\n   200\t    dir_fd = os.open(str(path.parent), os.O_RDONLY)\n   201\t    try:\n   202\t        os.fsync(dir_fd)\n   203\t    finally:\n   204\t        os.close(dir_fd)\n","exit_code":0,"status":"completed"}}
