environment error\n    31\t#   3  gate blocked: local-ci/summary is not success for the head SHA.  Nothing\n    32\t#      is published — the absence of a green local-review/summary is the block.\n    33\t#   4  the reviewer returned no machine-parseable verdict trailer.  A failing\n    34\t#      local-review/summary is posted so the PR never reads as green.\n    35\t#\n    36\t# Environment:\n    37\t#   LOCAL_REVIEW_ENABLED       disables the reviewer on the literal string\n    38\t#                              \"false\" only; unset means enabled.\n    39\t#   MIPSTARRE_TRUSTED_REF      git ref the reviewer personas are read from\n    40\t#                              (default: main).  Never the branch under review.\n    41\t#   MIPSTARRE_REVIEW_MODEL     codex model for the code review (default: the\n    42\t#                              dispatcher's / codex's own default)\n    43\t#   MIPSTARRE_PROSE_MODEL      codex model for the blueprint prose review\n    44\t#                              (default: MIPSTARRE_REVIEW_MODEL)\n    45\t#   MIPSTARRE_CACHE_ROOT        runtime state root (default ~/.cache/mipstarre-dev)\n    46\t#   MIPSTARRE_REVIEW_LOCK_WAIT seconds to queue behind another review of the\n    47\t#                              same PR before giving up (default 1800)\n    48\t#   MIPSTARRE_DIFF_MAX_LINES   diff lines handed to the reviewer (default 4000)\n    49\t#   MIPSTARRE_GITHUB_REPO      owner/repo override for gh_common.py\n    50\t#\n    51\tset -euo pipefail\n    52\t\n    53\tPROG=\"review.sh\"\n    54\tBIN_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\n    55\tSELF_ROOT=\"$(cd \"$BIN_DIR/../..\" && pwd)\"\n    56\tROOT=\"$SELF_ROOT\"\n    57\t# Worktrees are administered from the PRIMARY checkout: when this script runs\n    58\t# from a linked worktree copy, re-point the git root at the primary (same\n    59\t# resolution as cache-warmer.sh resolve_primary_repo; EVOLUTION.md 2026-08-30).\n    60\t# Git operations AND the telemetry ledger copy follow the re-point (telemetry\n    61\t# is single-instance in the primary, like builds.jsonl); gh_common.py ships\n    62\t# beside this script and needs no re-point.\n    63\t_common=\"$(git -C \"$ROOT\" rev-parse --path-format=absolute --git-common-dir 2>/dev/null || true)\"\n    64\tcase \"$_common\" in\n    65\t  */.git) ROOT=\"$(dirname \"$_common\")\" ;;\n    66\tesac\n    67\tunset _common\n    68\t\n    69\t# The one GitHub layer (gh_common.py:6-8); it ships beside this script.\n    70\tGH_COMMON=\"$BIN_DIR/gh_common.py\"\n    71\tCACHE=\"${MIPSTARRE_CACHE_ROOT:-$HOME/.cache/mipstarre-dev}\"\n    72\tTRUSTED_REF=\"${MIPSTARRE_TRUSTED_REF:-main}\"\n    73\tDISPATCH=\"$ROOT/local/bin/dispatch.sh\"\n    74\tREVIEW_MODEL=\"${MIPSTARRE_REVIEW_MODEL:-}\"\n    75\tPROSE_MODEL=\"${MIPSTARRE_PROSE_MODEL:-$REVIEW_MODEL}\"\n    76\tLOCK_WAIT=\"${MIPSTARRE_REVIEW_LOCK_WAIT:-1800}\"\n    77\tDIFF_MAX_LINES=\"${MIPSTARRE_DIFF_MAX_LINES:-4000}\"\n    78\tBOT_PREFIX_RE='^\\[(claude|codex)-(auto|review)-fix\\]'\n    79\t\n    80\tLOCK_HELD=\"\"\n    81\t\n    82\tlog()  { printf '%s: %s\\n' \"$PROG\" \"$*\" >&2; }\n    83\twarn() { printf '%s: warning: %s\\n' \"$PROG\" \"$*\" >&2; }\n    84\tdie()  { printf '%s: error: %s\\n' \"$PROG\" \"$*\" >&2; exit 1; }\n    85\t\n    86\tcleanup() {\n    87\t  local rc=$?\n    88\t  if [ -n \"$LOCK_HELD\" ] && [ -d \"$LOCK_HELD\" ]; then\n    89\t    rm -rf \"$LOCK_HELD\"\n    90\t    LOCK_HELD=\"\"\n    91\t  fi\n    92\t  exit \"$rc\"\n    93\t}\n    94\ttrap cleanup EXIT INT TERM\n    95\t\n    96\t# ---------------------------------------------------------------- utilities\n    97\t\n    98\tnow_utc() { date -u +%Y-%m-%dT%H:%M:%SZ; }\n    99\t\n   100\t# ghc <subcommand> ... — the only way this script talks to GitHub.  gh_common.py\n   101\t# exits 2 with the reason on stderr and never writes a local fallback record\n   102\t# (gh_common.py:19-20), so every caller here fails closed.\n   103\tghc() { python3 \"$GH_COMMON\" \"$@\"; }\n   104\t\n   105\t# json_get <file> <dotted-path> — one scalar out of a gh_common JSON payload.\n   106\t# Absent keys print an empty line, so callers test with [ -n ... ] as they did\n   107\t# with the frontmatter reader this replaces.\n   108\tjson_get() {\n   109\t  python3 - \"$1\" \"$2\" <<'PY'\n   110\timport json, sys\n   111\ttry:\n   112\t    data = json.load(open(sys.argv[1], encoding=\"utf-8\"))\n   113\texcept Exception as exc:\n   114\t    sys.stderr.write(\"review.sh: unreadable GitHub payload %s: %s\\n\" % (sys.argv[1], exc))\n   115\t    raise SystemExit(1)\n   116\tfor part in sys.argv[2].split(\".\"):\n   117\t    data = data.get(part) if isinstance(data, dict) else None\n   118\tprint(\"\" if data is None else data)\n   119\tPY\n   120\t}\n   121\t\n   122\t# post_summary <state> <description> — the local-review/summary commit status on\n   123\t# the exact head SHA.  This status, not a review state, is what pr_merge.py\n   124\t# reads: an adverse verdict posts as a COMMENT review plus a failing status\n   125\t# (local/protocols/issues-prs.md).\n   126\tpost_summary() {\n   127\t  ghc post-status \"$HEAD_SHA\" local-review/summary \"$1\" --desc \"$2\" ||\n   128\t    warn \"could not post local-review/summary=$1 for $HEAD_SHA; the PR stays ungreen\"\n   129\t}\n   130\t\n   131\t# sanitize_to <src> <dest> <max-lines> — control-char strip, fence breaking,\n   132\t# truncation (DESIGN.md invariant 6).  dispatch.sh sanitizes attachments again;\n   133\t# this is the copy that also protects the no-dispatcher fallback path.\n   134\tsanitize_to() {\n   135\t  python3 - \"$1\" \"$2\" \"$3\" <<'PY'\n   136\timport sys\n   137\tsrc, dest, max_lines = sys.argv[1], sys.argv[2], int(sys.argv[3])\n   138\ttry:\n   139\t    raw = open(src, encoding=\"utf-8\", errors=\"replace\").read()\n   140\texcept OSError:\n   141\t    raw = \"\"\n   142\traw = raw.replace(\"\\r\\n\", \"\\n\").replace(\"\\r\", \"\\n\")\n   143\tkeep = []\n   144